#!/usr/bin/env bash
# Build both legs of a wave-32 CHECKMULTISIG cell.
#
#   build_cell.sh <cell_dir> alive2|saw <c_src> <l_src> <cell_id> [checker]
#
# The L leg includes twin_ops.h, generated by cells/_tools/mk_leaf.py from
# twin/ops_ir.py for the TwinErr enum and core_ord().  No handler body is
# used: the CHECKMULTISIG prelude/loop transliterations live in the cell.
set -euo pipefail

CELL_DIR="$1"; MODE="$2"; C_SRC="$3"; L_SRC="$4"; ID="$5"; CHECKER="${6:-}"
E3="$(cd "$(dirname "$0")" && pwd)"
CELLS="$(cd "$E3/../.." && pwd)"
EQ="$(cd "$CELLS/.." && pwd)"
BUILD="$CELL_DIR/build"
mkdir -p "$BUILD"

python3 "$CELLS/_tools/mk_leaf.py" \
  --ops OP_UNSUPPORTED_CHECKSIG --max-depth 64 --max-elem 2 \
  --out "$BUILD/twin_ops.h" --meta "$BUILD/twin_ops.meta.json" 2>/dev/null
python3 "$CELLS/_tools/mk_leaf.py" \
  --ops OP_UNSUPPORTED_CHECKSIG --max-depth 64 --max-elem 2 \
  --check "$BUILD/twin_ops.h" 2>/dev/null

CXX=(/usr/bin/clang++-20 -std=c++17 -I "$E3" -I "$BUILD" -I "$EQ/contract"
     -fno-discard-value-names -fno-strict-aliasing)
LLVM=/usr/lib/llvm-20/bin

if [ "$MODE" = "alive2" ]; then
  # -O2, not -O1: at -O1 clang tags every loop with
  # "llvm.loop.unroll.disable", and Alive2 v20.0 then does not unroll the
  # bounded loops in the loop/finddelete cells; executions that do not reach
  # a return within its unroll budget are treated as unconstrained, which
  # makes the comparison vacuous (measured: a fd_pack mutant and a
  # loop-encoding-order mutant both came back "correct" at -O1 and are both
  # caught at -O2).  -O2 emits the same bounded loops without that tag and
  # Alive2 unrolls them; the SAW lane stays at -O0.
  "${CXX[@]}" -O2 -S -emit-llvm "$E3/$C_SRC" -o "$BUILD/c_leaf.ll"
  "${CXX[@]}" -O2 -S -emit-llvm "$E3/$L_SRC" -o "$BUILD/l_leaf.ll"
  {
    printf 'mode=alive2 cell=%s\n' "$ID"
    printf 'clang=%s\n' "$(/usr/bin/clang++-20 --version | head -1)"
    printf 'llvm=%s\n' "$("$LLVM/llvm-extract" --version | head -1)"
    printf 'c_src_sha256=%s\n' "$(sha256sum "$E3/$C_SRC" | cut -d' ' -f1)"
    printf 'l_src_sha256=%s\n' "$(sha256sum "$E3/$L_SRC" | cut -d' ' -f1)"
    printf 'twin_ops_sha256=%s\n' "$(sha256sum "$BUILD/twin_ops.h" | cut -d' ' -f1)"
    printf 'c_leaf_sha256=%s\n' "$(sha256sum "$BUILD/c_leaf.ll" | cut -d' ' -f1)"
    printf 'l_leaf_sha256=%s\n' "$(sha256sum "$BUILD/l_leaf.ll" | cut -d' ' -f1)"
  } > "$BUILD/build.txt"
else
  "${CXX[@]}" -O0 -c -emit-llvm "$E3/$C_SRC" -o "$BUILD/c_leaf.bc"
  "${CXX[@]}" -O0 -c -emit-llvm "$E3/$L_SRC" -o "$BUILD/l_leaf.bc"
  CB="$BUILD/c_leaf.bc"; LB="$BUILD/l_leaf.bc"
  if [ -n "$CHECKER" ]; then
    "${CXX[@]}" -O0 -c -emit-llvm -DBTC_EQUIV_CHECKER_RESULT="$CHECKER" \
      "$E3/checker_stub.cpp" -o "$BUILD/checker_stub_${CHECKER}.bc"
    "$LLVM/llvm-link" "$BUILD/c_leaf.bc" "$BUILD/checker_stub_${CHECKER}.bc" \
      -o "$BUILD/c_leaf_saw_${CHECKER}.bc"
    "$LLVM/llvm-link" "$BUILD/l_leaf.bc" "$BUILD/checker_stub_${CHECKER}.bc" \
      -o "$BUILD/l_leaf_saw_${CHECKER}.bc"
    CB="$BUILD/c_leaf_saw_${CHECKER}.bc"; LB="$BUILD/l_leaf_saw_${CHECKER}.bc"
  else
    CB="$BUILD/c_leaf_saw.bc"; LB="$BUILD/l_leaf_saw.bc"
    cp "$BUILD/c_leaf.bc" "$CB"; cp "$BUILD/l_leaf.bc" "$LB"
  fi
  "$LLVM/llvm-dis" "$CB" -o "${CB%.bc}.ll"
  "$LLVM/llvm-dis" "$LB" -o "${LB%.bc}.ll"
  {
    printf 'mode=saw cell=%s checker=%s\n' "$ID" "${CHECKER:-none}"
    printf 'clang=%s\n' "$(/usr/bin/clang++-20 --version | head -1)"
    printf 'llvm=%s\n' "$("$LLVM/llvm-link" --version | head -1)"
    printf 'c_src_sha256=%s\n' "$(sha256sum "$E3/$C_SRC" | cut -d' ' -f1)"
    printf 'l_src_sha256=%s\n' "$(sha256sum "$E3/$L_SRC" | cut -d' ' -f1)"
    printf 'twin_ops_sha256=%s\n' "$(sha256sum "$BUILD/twin_ops.h" | cut -d' ' -f1)"
    printf 'c_bc_sha256=%s\n' "$(sha256sum "$CB" | cut -d' ' -f1)"
    printf 'l_bc_sha256=%s\n' "$(sha256sum "$LB" | cut -d' ' -f1)"
  } > "$BUILD/build_saw_${CHECKER:-none}.txt"
fi
